/**
 * Writes `src/app/data/ev-by-count.generated.ts`: what the hands with a published
 * index are worth at each true count.
 *
 * Run with:  npm run export:ev-counts
 *
 * Slow on purpose: it deals tens of thousands of depleted shoes and solves every
 * indexed hand exactly on each one, across several processes. So unlike the
 * full-shoe table it is regenerated by hand when the solver or the rule list
 * changes, not on every CI run. The sampling is seeded, so a run reproduces, and
 * `ev-by-count.spec.ts` holds the published indices to the committed values.
 */
import { spawn } from 'node:child_process';
import { mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import { H17_DEVIATIONS } from '../../src/app/data/h17-deviations';
import { S17_DEVIATIONS } from '../../src/app/data/s17-deviations';
import {
  hardForms,
  insuranceByCount,
  sampleShoes,
  valuesByCount,
  type SampledShoe,
  type TwoCardForm,
} from './count-sampler';
import { ACE, type TableRules } from './solver';

const HERE = fileURLToPath(import.meta.url);
const ROOT = join(dirname(HERE), '..', '..');
const OUT = join(ROOT, 'src', 'app', 'data', 'ev-by-count.generated.ts');

const DECKS = 6;
// The published range the drills deal, with a margin. The shoes are sampled wider
// than this, so a hand's own cards cannot push the ends of it out of the pool.
const MIN_COUNT = -7;
const MAX_COUNT = 9;
const PER_BUCKET = 1500;
const SEED = 20261031;
const WORKERS = 6;

interface Cell {
  readonly ruleSet: 'H17' | 'S17';
  readonly key: string; // `hard-16-v-10`, the tally's own spelling
  readonly hand: string;
  readonly kind: 'hard' | 'soft' | 'pair';
  readonly up: number;
}

function upRank(upcard: string): number {
  return upcard === 'A' ? ACE : Number(upcard);
}

// Every hand with an index, once: a surrender index and a playing index over the
// same hand are one cell, read at two plays.
function cells(): readonly Cell[] {
  const out = new Map<string, Cell>();
  for (const rule of [...H17_DEVIATIONS, ...S17_DEVIATIONS]) {
    if (rule.category === 'insurance') continue;
    const kind = rule.category === 'surrender' ? 'hard' : rule.category;
    const key = `${rule.ruleSet}:${kind}-${rule.playerHand}-v-${rule.dealerUpcard}`;
    out.set(key, {
      ruleSet: rule.ruleSet,
      key: `${kind}-${rule.playerHand}-v-${rule.dealerUpcard}`,
      hand: rule.playerHand,
      kind,
      up: upRank(rule.dealerUpcard),
    });
  }
  return [...out.values()];
}

function formsOf(cell: Cell): readonly TwoCardForm[] {
  switch (cell.kind) {
    case 'hard':
      return hardForms(Number(cell.hand));
    case 'soft':
      return [{ a: ACE, b: Number(cell.hand) - 11 }];
    case 'pair': {
      const rank = cell.hand === 'A' ? ACE : Number(cell.hand);
      return [{ a: rank, b: rank }];
    }
  }
}

function pool(): readonly SampledShoe[] {
  const buckets = sampleShoes({
    decks: DECKS,
    // A cut card at three quarters, and past the first round of a fresh shoe.
    minDealt: 0.5,
    maxDealt: 4.5,
    minCount: MIN_COUNT - 1,
    maxCount: MAX_COUNT + 1,
    perBucket: PER_BUCKET,
    seed: SEED,
    maxDraws: 12_000_000,
  });
  return [...buckets.values()].flat();
}

function counts(): readonly number[] {
  const out: number[] = [];
  for (let tc = MIN_COUNT; tc <= MAX_COUNT; tc++) out.push(tc);
  return out;
}

function units(value: number): number {
  return Math.round(value * 10_000);
}

type Columns = Record<string, readonly number[]>;

// One slice of the cells, in one process. DAS is fixed on: the only indexed split
// is tens at a high count, where a double after a split barely enters into it.
function work(part: number, parts: number, file: string): void {
  const shoes = pool();
  const result: { ruleSet: string; key: string; columns: Columns }[] = [];
  cells().forEach((cell, i) => {
    if (i % parts !== part) return;
    const rules: TableRules = {
      h17: cell.ruleSet === 'H17',
      das: true,
      maxHands: 4,
      blackjackPays: 1.5,
    };
    const byCount = valuesByCount(shoes, formsOf(cell), cell.up, rules);
    const read = (pick: (v: NonNullable<ReturnType<typeof byCount.get>>) => number | null) =>
      counts().map((tc) => {
        const values = byCount.get(tc);
        const value = values ? pick(values) : null;
        if (value === null) throw new Error(`${cell.key}: nothing sampled at TC ${tc}`);
        return units(value);
      });
    const columns: Columns = {
      stand: read((v) => v.stand),
      hit: read((v) => v.hit),
      double: read((v) => v.double),
    };
    if (cell.kind === 'pair') columns['split'] = read((v) => v.split);
    result.push({ ruleSet: cell.ruleSet, key: cell.key, columns });
    // eslint-disable-next-line no-console
    console.log(`${cell.ruleSet} ${cell.key}`);
  });
  writeFileSync(file, JSON.stringify(result));
}

async function main(): Promise<void> {
  const dir = mkdtempSync(join(tmpdir(), 'ev-counts-'));
  const files = Array.from({ length: WORKERS }, (_, i) => join(dir, `part-${i}.json`));
  await Promise.all(
    files.map(
      (file, i) =>
        new Promise<void>((resolve, reject) => {
          const child = spawn(
            process.execPath,
            // One GC thread each: six allocating workers otherwise spawn enough
            // collector threads to bring the rest of the machine to a crawl.
            [
              '--single-threaded-gc',
              '--import',
              'tsx',
              HERE,
              'worker',
              String(i),
              String(WORKERS),
              file,
            ],
            { stdio: 'inherit' },
          );
          child.on('exit', (code) =>
            code === 0 ? resolve() : reject(new Error(`worker ${i} exited ${code}`)),
          );
        }),
    ),
  );

  const merged: Record<string, Record<string, Columns>> = { H17: {}, S17: {} };
  for (const file of files) {
    const part = JSON.parse(readFileSync(file, 'utf8')) as {
      ruleSet: string;
      key: string;
      columns: Columns;
    }[];
    for (const { ruleSet, key, columns } of part) merged[ruleSet][key] = columns;
  }
  rmSync(dir, { recursive: true, force: true });

  const sorted = (table: Record<string, Columns>) =>
    Object.fromEntries(Object.entries(table).sort(([a], [b]) => a.localeCompare(b)));

  const insurance = insuranceByCount(pool());
  const data = {
    decks: DECKS,
    minCount: MIN_COUNT,
    maxCount: MAX_COUNT,
    insurance: counts().map((tc) => units(insurance.get(tc) ?? Number.NaN)),
    cells: { H17: sorted(merged['H17']), S17: sorted(merged['S17']) },
  };
  const body = JSON.stringify(data, null, 1).replace(
    /\[\n\s+([-\d\s,]+?)\n\s+\]/g,
    (_match, cells: string) => `[${cells.replace(/\s+/g, '')}]`,
  );
  writeFileSync(
    OUT,
    '// GENERATED by tools/ev/export-count-values.ts (npm run export:ev-counts). Do\n' +
      '// not edit. Sampled and seeded, so it is regenerated by hand: see that file.\n' +
      "import type { EvByCount } from '../core/models/ev.model';\n\n" +
      `export const EV_BY_COUNT: EvByCount = ${body};\n`,
  );
  // eslint-disable-next-line no-console
  console.log(`Wrote ${OUT}`);
}

if (process.argv[2] === 'worker') {
  work(Number(process.argv[3]), Number(process.argv[4]), process.argv[5]);
} else {
  void main();
}
